'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[6,1,3],[8,3,4],[4,1,4],[6,2,3],[8,1,4],[4,3,4]];
let variant=OrionProgress.variant('probability'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,red=1,blue=1,choice='',tallies=[0,0],last=-1,solved=false,hintDepth=0,state='ready',saveFailed=false,running=false,timer=null,epoch=0;
function challenge(v=variant,s=stage){const [total,numerator,denominator]=journeys[v];return {total,numerator,denominator,favoured:v%2===0?'red':'blue',kind:s};}
function total(){return red+blue;}
function comparison(){return red>blue?'red':red<blue?'blue':'equal';}
function designMatches(q=challenge()){return red>0&&blue>0&&total()===q.total&&(q.kind===0?comparison()===q.favoured:q.kind===1?red===blue:red*q.denominator===q.numerator*total());}
function stopDraw(){epoch++;if(timer!==null)clearTimeout(timer);timer=null;running=false;}
function resetTrial(){stopDraw();red=1;blue=1;choice='';tallies=[0,0];last=-1;solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('probability')){variant=v;stage=0;resetTrial();}
function adjust(colour,n){if(solved||running||!['red','blue'].includes(colour)||!Number.isInteger(n)||n<0||n>8)return;if((colour==='red'?red:blue)===n)return;if(colour==='red')red=n;else blue=n;tallies=[0,0];last=-1;choice='';state='ready';render();}
function choose(c){if(solved||running||!['red','blue','equal'].includes(c))return;choice=c;state='ready';render();}
function sample(u=Math.random()){if(total()===0||!Number.isFinite(u)||u<0||u>=1)return -1;return Math.floor(u*total())<red?0:1;}
function draw(){if(solved||running||total()===0||tallies[0]+tallies[1]>=100)return;running=true;state='ready';const token=++epoch;let remaining=Math.min(10,100-tallies[0]-tallies[1]);const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;function tick(){if(token!==epoch)return;last=sample();tallies[last]++;remaining--;if(!remaining){running=false;timer=null;render();return;}render();if(reduced)tick();else timer=setTimeout(tick,220);}tick();}
function check(){if(solved||running)return;if(!designMatches())state='design';else if(tallies[0]+tallies[1]<10)state='observe';else if(!choice)state='choose';else if(choice!==comparison())state='compare';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('possibility');}render();if(solved&&stage<2)$('next').focus();}
function hints(){const q=challenge(),r=q.kind===0?(q.favoured==='red'?q.total-1:1):q.kind===1?q.total/2:q.total*q.numerator/q.denominator;return[t('Count the gems in the bag, not just the colours. Each individual gem has the same chance of being picked.','數一數袋裏的寶石，不只是顏色種類。每顆寶石被抽中的機會相同。'),t('A colour’s chance is its gem count divided by the total. Replacing the gem keeps the next draw’s chances unchanged. A short tally can be uneven.','某顏色的機會等於該色數量除以總數。放回寶石，下一次機會不變。短期紀錄可能不平均。'),t(`One design: ${r} red and ${q.total-r} blue. Draw at least 10 times, then choose ${r>q.total-r?'Red':r<q.total-r?'Blue':'Equal'} for the NEXT draw.`,`其中一個設計：${r} 紅、${q.total-r} 藍。抽至少 10 次，再選下一次的機會：${r>q.total-r?'紅色較大':r<q.total-r?'藍色較大':'相同'}。`)];}
function gem(col,x,y){return col===0?`<path d="M${x} ${y-13}L${x+12} ${y}L${x} ${y+13}L${x-12} ${y}Z" fill="#e77d86" stroke="#ffd0bd" stroke-width="2"/>`:`<circle cx="${x}" cy="${y}" r="12" fill="#71b9e7" stroke="#c4ecff" stroke-width="2"/>`;}
function render(){const q=challenge(),complete=solved&&stage===2,progress=stage+Number(solved),n=total(),draws=tallies[0]+tallies[1];window.OrionDiscovery?.update(complete);document.title=t('The Chance Compass · Orion','機遇羅盤 · Orion');$('stageTitle').textContent=t(`Passage ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 條通道 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Compass seals · ${progress} / 3`,`羅盤封印 · ${progress} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
let stones='';for(let i=0;i<n;i++)stones+=gem(i<red?0:1,93+(i%8)*28,78+Math.floor(i/8)*35);
$('bag').innerHTML=`<svg viewBox="0 0 400 190" aria-hidden="true"><path d="M80 30Q200 15 320 30L340 130Q340 166 300 169H100Q60 166 60 130Z" fill="#183f4966" stroke="#c7b27e" stroke-width="3"/><path d="M80 30Q200 53 320 30" fill="none" stroke="#c7b27e" stroke-width="3"/>${stones}<text x="200" y="151" text-anchor="middle" fill="#f1d896" font-size="17">${t(`${n} gems in bag`, `袋中 ${n} 顆寶石`)}</text></svg>`;
$('bag').setAttribute('aria-label',t(`Transparent bag: ${red} red diamond gems, ${blue} blue round gems.`,`透明袋：${red} 顆紅色菱形寶石、${blue} 顆藍色圓形寶石。`));for(const [id,count] of [['red',red],['blue',blue]]){$(id).value=count;$(id).disabled=solved||running;$(id+'Count').textContent=count;$(id+'Less').disabled=solved||running||count===0;$(id+'More').disabled=solved||running||count===8;}
const target=q.kind===0?t(`Make ${q.favoured==='red'?'red':'blue'} more likely than the other colour.`,`讓${q.favoured==='red'?'紅':'藍'}色比另一色更有機會。`):q.kind===1?t('Give both colours an equal chance.','讓兩種顏色機會相同。'):t(`Give red a ${q.numerator}/${q.denominator} chance.`,`讓紅色的機會是 ${q.numerator}/${q.denominator}。`);
$('goal').textContent=t(`Use exactly ${q.total} gems, with both colours present. `,`使用剛好 ${q.total} 顆寶石，兩種顏色都要有。`)+target;
$('chances').innerHTML=n?`<strong>${t('Chance on each draw','每次抽取的機會')}</strong><div class="chance-row"><span>♦ ${t('Red','紅色')}</span><span>${red}/${n}</span></div><div class="chance-row"><span>● ${t('Blue','藍色')}</span><span>${blue}/${n}</span></div>`:t('The bag is empty. Add a gem to explore.','袋子是空的。加入寶石來探索。');
$('tally').innerHTML=`<strong>${t('Observed draws','抽取紀錄')}: ${draws} / 100</strong><div>♦ ${t('Red','紅色')}: ${tallies[0]} · ● ${t('Blue','藍色')}: ${tallies[1]}</div><div class="${running?'draw-gem':''}">${last<0?t('No draws yet','尚未抽取'):t(`Last: ${last===0?'♦ Red':'● Blue'} → replaced`,`上次：${last===0?'♦ 紅色':'● 藍色'} → 已放回`)}</div>`;
for(const [id,c] of [['chooseRed','red'],['chooseEqual','equal'],['chooseBlue','blue']]){$(id).setAttribute('aria-pressed',String(choice===c));$(id).disabled=solved||running;}
$('draw').disabled=solved||running||!n||draws>=100;$('stop').hidden=!running;$('check').disabled=running;
const messages={ready:['Build, observe, and explain. Your design earns the seal, not lucky draws.','設計、觀察、解釋。封印取決於設計，不靠幸運抽取。'],design:['Check the required total, both colours, and the target chance. You can change your bag and try again.','看看總數、兩種顏色和目標機會是否符合。可以改變袋子再試。'],observe:['Your bag fits! Draw and replace at least 10 gems to explore its results.','袋子符合要求！抽取並放回至少 10 次，探索結果。'],choose:['Choose which colour is more likely on the next draw, or Equal.','選擇下一次較有機會的顏色，或選「相同」。'],compare:['Look at what is IN the bag. Past draws do not change the next draw’s chances.','看看袋子裏有甚麼。之前的結果不會改變下一次的機會。'],success:['Your design and explanation fit. A compass seal shines!','設計和解釋都正確，羅盤封印亮起了！']};$('feedback').textContent=t(...messages[state]);
$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('possibility')?t('Possibility Sigil saved in your collection.','可能符印已存入收藏。'):'';}
for(const c of ['red','blue']){$(c).oninput=()=>adjust(c,Number($(c).value));$(c+'Less').onclick=()=>adjust(c,(c==='red'?red:blue)-1);$(c+'More').onclick=()=>adjust(c,(c==='red'?red:blue)+1);}
$('chooseRed').onclick=()=>choose('red');$('chooseEqual').onclick=()=>choose('equal');$('chooseBlue').onclick=()=>choose('blue');$('draw').onclick=draw;$('stop').onclick=()=>{stopDraw();render();};$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('red').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('probability',variant);observedVariant=OrionProgress.variant('probability');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('possibility');render();};
function syncProgress(){const v=OrionProgress.variant('probability'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('possibility')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);window.addEventListener('pagehide',stopDraw);resetMission();OrionI18n.apply();
